<script setup lang="ts">
import type {Palette,ThemeMode} from '../design/themes.ts';
const props=defineProps<{mode:ThemeMode;palette:Palette}>();
const emit=defineEmits<{select:[mode:ThemeMode]}>();
const choices=[{id:'system',label:'跟随系统'},{id:'light',label:'浅色'},{id:'dark',label:'深色'}] as const;
function style(mode:'light'|'dark'){const [bg,ink,accent]=props.palette[mode];return {'--mini-bg':bg,'--mini-ink':ink,'--mini-accent':accent,'--mode-card-bg':bg,'--mode-card-text':ink};}
function keyboard(event:KeyboardEvent,index:number){const delta=event.key==='ArrowLeft'?-1:event.key==='ArrowRight'?1:0;if(!delta&&event.key!=='Home'&&event.key!=='End')return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?2:(index+delta+3)%3;emit('select',choices[next]!.id);(event.currentTarget as HTMLElement).parentElement?.querySelectorAll<HTMLButtonElement>('button')[next]?.focus();}
</script>
<template><div class="theme-mode-setting"><span id="appearance-mode-label">显示模式</span><div class="theme-mode-cards palette-pair" role="group" aria-labelledby="appearance-mode-label">
 <button v-for="(choice,index) in choices" :key="choice.id" type="button" class="theme-mode-card palette-preview" :data-preview-mode="choice.id" :aria-pressed="mode===choice.id" :aria-label="choice.label" :style="choice.id==='system'?{}:style(choice.id)" @click="emit('select',choice.id)" @keydown="keyboard($event,index)">
  <span class="mini-screen" :class="{'split-screen':choice.id==='system'}" aria-hidden="true"><span v-for="variant in (choice.id==='system'?['light','dark'] as const:[choice.id] as const)" :key="variant" class="mini-window" :style="style(variant)"><span class="mini-rail"><i class="mini-brand"/></span><span class="mini-content"><span class="mini-toolbar"><i/><i/><i/></span><span class="mini-plot"><svg viewBox="0 0 100 36" preserveAspectRatio="none"><path class="mini-axis" d="M3 2V32H98"/><path class="mini-wave" d="M4 18H10L13 13L16 25L19 8L22 29L25 14L28 20L31 18H38L41 9L44 30L47 4L50 32L53 12L56 23L59 18H66L69 12L72 25L75 7L78 29L81 14L84 20L87 18H98"/></svg></span><span class="mini-status"><i/><i/></span></span></span></span>
  <small>{{choice.label}}</small>
 </button>
</div></div></template>
<style scoped>
.theme-mode-setting{display:grid;gap:9px}.theme-mode-setting>span{font-weight:550}.theme-mode-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:9px;border-radius:15px;background:color-mix(in srgb,var(--panel) 50%,transparent);border:1px solid var(--border)}.theme-mode-card{position:relative;display:flex;flex-direction:column;gap:8px;min-width:0;min-height:112px;padding:9px 7px;border-radius:11px;overflow:hidden;white-space:normal}.theme-mode-card small{position:static;font-size:.785714rem;color:inherit;line-height:1.2}.mini-screen{display:flex;width:100%;max-width:134px;height:70px;min-width:0;overflow:hidden;border-radius:7px;box-shadow:0 1px 4px #0002}.mini-window{display:flex;width:100%;height:100%;min-width:0;background:var(--mini-bg);color:var(--mini-ink);border:1px solid color-mix(in srgb,var(--mini-ink) 15%,transparent);border-radius:6px;padding:4px;gap:5px;overflow:hidden}.split-screen .mini-window{width:50%;border-radius:5px 0 0 5px}.split-screen .mini-window+ .mini-window{border-radius:0 5px 5px 0}.mini-rail{width:14px;flex:none;display:flex;justify-content:center;border-right:1px solid color-mix(in srgb,var(--mini-ink) 15%,transparent);background:color-mix(in srgb,var(--mini-ink) 4%,var(--mini-bg));padding-top:3px}.mini-brand{width:7px;height:7px;border:1px solid currentColor;border-radius:50%;opacity:.4}.mini-content{display:flex;flex:1;min-width:0;flex-direction:column;gap:3px;padding-top:2px}.mini-toolbar{display:flex;gap:3px;height:8px;flex:none;border-bottom:1px solid color-mix(in srgb,var(--mini-ink) 15%,transparent)}.mini-toolbar i{width:12px;height:4px;background:var(--mini-accent);opacity:.5;border-radius:1px}.mini-plot{flex:1;min-height:0;background:color-mix(in srgb,var(--mini-ink) 4%,var(--mini-bg));border:1px solid color-mix(in srgb,var(--mini-ink) 12%,transparent);padding:3px}.mini-plot svg{display:block;width:100%;height:100%;fill:none}.mini-axis{stroke:var(--mini-ink);stroke-width:1;opacity:.3}.mini-wave{stroke:var(--mini-accent);stroke-width:1.6}.mini-status{height:5px;display:flex;gap:4px;flex:none}.mini-status i{width:25%;height:2px;background:var(--mini-ink);opacity:.25}

@container module (max-width:480px){.theme-mode-cards{gap:6px;padding:6px}.theme-mode-card{padding:6px 4px;min-height:104px}.mini-rail{width:10px}.mini-window{gap:3px;padding:3px}}
</style>
